"use client";

import { Children, type HTMLAttributes, type ReactNode, useCallback, useEffect, useRef, useState } from "react";
import { cx } from "../utils/cx";
import { prefersReducedMotion } from "../utils/motion";
import { ChevronLeftIcon, ChevronRightIcon } from "../icons/interface";

export type CarouselProps = Omit<HTMLAttributes<HTMLElement>, "children"> & {
  /** Names the carousel (required). */
  "aria-label": string;
  /** Each child is one slide. */
  children: ReactNode;
  /** How many slides fit across. Default 1. */
  perView?: number;
  /** Gap between slides, CSS length. Default 1rem. */
  gap?: string;
  /** Advance on a timer, ms. Stops on hover and focus, and never runs under reduced motion. */
  autoplay?: number;
  /** Show the position dots. Default true. */
  dots?: boolean;
  /** Controlled and initial slide (zero-based). */
  index?: number;
  onIndexChange?: (index: number) => void;
};

/**
 * A scroll-snap carousel: touch and trackpad scrolling are native, buttons and the arrow keys move a slide at a time
 * with an eased scroll, and the dots stretch to show where you are. Each child is a slide announced as "N of M".
 */
export function Carousel({
  children,
  perView = 1,
  gap = "1rem",
  autoplay,
  dots = true,
  index: controlled,
  onIndexChange,
  className,
  style,
  onKeyDown,
  ...rest
}: CarouselProps) {
  const slides = Children.toArray(children);
  const count = slides.length;
  const track = useRef<HTMLDivElement>(null);
  const [inner, setInner] = useState(0);
  const index = controlled ?? inner;
  const [paused, setPaused] = useState(false);
  const last = Math.max(0, count - perView);

  const goTo = useCallback(
    (to: number, behavior?: ScrollBehavior) => {
      const el = track.current;
      const target = Math.max(0, Math.min(last, to));
      const slide = el?.children[target] as HTMLElement | undefined;
      if (!el || !slide) return;
      el.scrollTo({
        left: slide.offsetLeft - el.offsetLeft,
        behavior: behavior ?? (prefersReducedMotion(el) ? "auto" : "smooth"),
      });
    },
    [last],
  );

  // report the slide nearest the left edge while scrolling (a frame at a time)
  useEffect(() => {
    const el = track.current;
    if (!el) return;
    let raf = 0;
    const onScroll = () => {
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = 0;
        let best = 0;
        let dist = Number.POSITIVE_INFINITY;
        Array.from(el.children).forEach((c, i) => {
          const d = Math.abs((c as HTMLElement).offsetLeft - el.offsetLeft - el.scrollLeft);
          if (d < dist) {
            dist = d;
            best = i;
          }
        });
        best = Math.min(best, last);
        setInner(best);
        if (best !== index) onIndexChange?.(best);
      });
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      el.removeEventListener("scroll", onScroll);
      cancelAnimationFrame(raf);
    };
  }, [last, index, onIndexChange]);

  // controlled index: scroll when it changes from outside
  const synced = useRef(index);
  useEffect(() => {
    if (controlled !== undefined && controlled !== synced.current) goTo(controlled);
    synced.current = index;
  }, [controlled, index, goTo]);

  useEffect(() => {
    if (!autoplay || paused || count <= perView) return;
    const el = track.current;
    if (el && prefersReducedMotion(el)) return;
    const t = setInterval(() => goTo(index >= last ? 0 : index + 1), autoplay);
    return () => clearInterval(t);
  }, [autoplay, paused, index, last, count, perView, goTo]);

  return (
    <section
      {...rest}
      aria-roledescription="carousel"
      className={cx("hm-carousel", className)}
      style={{ "--_per": perView, "--_gap": gap, ...style } as React.CSSProperties}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
      onKeyDown={(e) => {
        onKeyDown?.(e);
        if (e.defaultPrevented) return;
        if (e.key === "ArrowRight") goTo(index + 1);
        else if (e.key === "ArrowLeft") goTo(index - 1);
        else return;
        e.preventDefault();
      }}
    >
      <div ref={track} className="hm-carousel-track" tabIndex={0} aria-live={autoplay && !paused ? "off" : "polite"}>
        {slides.map((slide, i) => (
          <div
            key={i}
            role="group"
            aria-roledescription="slide"
            aria-label={`${i + 1} of ${count}`}
            className="hm-carousel-slide"
          >
            {slide}
          </div>
        ))}
      </div>
      <button
        type="button"
        className="hm-carousel-nav"
        data-side="prev"
        aria-label="Previous slide"
        disabled={index <= 0}
        onClick={() => goTo(index - 1)}
      >
        <ChevronLeftIcon size={14} strokeWidth={1.6} />
      </button>
      <button
        type="button"
        className="hm-carousel-nav"
        data-side="next"
        aria-label="Next slide"
        disabled={index >= last}
        onClick={() => goTo(index + 1)}
      >
        <ChevronRightIcon size={14} strokeWidth={1.6} />
      </button>
      {dots && count > perView ? (
        <div className="hm-carousel-dots">
          {Array.from({ length: last + 1 }, (_, i) => (
            <button
              key={i}
              type="button"
              className="hm-carousel-dot"
              aria-label={`Go to slide ${i + 1}`}
              aria-current={i === index ? "true" : undefined}
              onClick={() => goTo(i)}
            />
          ))}
        </div>
      ) : null}
    </section>
  );
}
